body #attract[style*="block"]:has(.arcover[style*="block"]) .arcover{ min-width:calc(var(--sp-5) * 15 * var(--attz,1)); }
/* v29.98 (cw-partyprompt), the critic on v29.97 (46, 55, 56, 64 = 3 each): "Press any button is an instruction drawn as a filled button, a fake action", "the logo out-shouts the title", "No scores yet is the one message that matters and it is small and dim", "the ring is unexplained". The prompt is a footer hint now: a button glyph and the words in the accent, pulsing, no fill. The wordmark is the 32px logo on the 5 percent margin. The empty line is 20px light, the seed line a 16px label, the table heads 20px. Restyle only. */
body #attract[style*="block"]:has(.arcpage[style*="block"]) .attpress, body #attract[style*="block"]:has(.arcover[style*="block"]) .attpress{ background:transparent; border-color:transparent; color:var(--acc); padding:0; min-width:0; gap:calc(var(--sp-1) * var(--attz,1)); animation:attpulse 1.6s ease-in-out infinite; }
body #attract[style*="block"]:has(.arcpage[style*="block"]) .attpress::before, body #attract[style*="block"]:has(.arcover[style*="block"]) .attpress::before{ content:''; flex:none; box-sizing:border-box; width:calc(var(--sp-3) * var(--attz,1)); height:calc(var(--sp-3) * var(--attz,1)); border:1px solid var(--acc); border-radius:50%; background:radial-gradient(circle, var(--acc) 0 35%, transparent 38%); }
body #attract[style*="block"]:has(.arcpage[style*="block"]) .arcpage, body #attract[style*="block"]:has(.arcover[style*="block"]) .arcover{ padding-bottom:calc((var(--sp-4) + var(--sp-3) + var(--btn-h)) * var(--attz,1)); }
body #attract[style*="block"]:has(.arcpage[style*="block"]) .attname{ left:5%; top:5%; font-size:calc(var(--fs-title) * var(--attz,1)); }
body #attract .arcpage .apn{ color:var(--tx-1); font-weight:700; }
body #attract .arcpage .apb{ font-size:calc(var(--fs-label) * var(--attz,1)); }
body #attract .arcpage .apg{ opacity:.6; }
body #attract .arcpage th{ font-size:calc(var(--fs-body) * var(--attz,1)); }
body #attract .arcpage .aprt{ margin-left:calc(var(--sp-1) * var(--attz,1)); font-size:calc(var(--fs-label) * var(--attz,1)); font-weight:600; color:var(--tx-2); }

check:
{v:'VER',what:'while an attract page or the run over card is up, Press any button is a footer hint (a button glyph and accent words, no fill, pulsing), the wordmark is the 32px (x scale) logo on the 5 percent margin, the empty board line is light, and the ring on how to play has two short words (critic on v29.97: 46 55 56 64 = 3 each; screens 46 52 55 56 64)',
 run:function(){
   if(typeof arcadeAttEl!=='function'||typeof arcadeAttHow!=='function'||typeof arcadeAttBoard!=='function'||typeof attEl!=='function') return 'SKIP: no arcade attract here';
   var d, pg, wasDisp, z, res=null, ap, cs, nm, probe, want, oldT, ln, wd;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     try{ if(typeof attZ==='function') attZ(d); }catch(_z){}
     z=parseFloat(d.style.getPropertyValue('--attz'))||1;
     pg=arcadeAttEl('arcpage'); pg.textContent=''; arcadeAttHow(pg); pg.style.display='block'; pg.style.translate='none'; pg.style.opacity='1'; try{ d.querySelectorAll('.uimghost').forEach(function(g){ g.remove(); }); }catch(_g){}
     ap=d.querySelector('.attpress'); cs=getComputedStyle(ap); nm=d.querySelector('.attname');
     probe=document.createElement('i'); probe.style.color='var(--acc)'; document.body.appendChild(probe); want=getComputedStyle(probe).color; probe.remove();
     wd=d.getBoundingClientRect().width;
     if(cs.backgroundColor!=='rgba(0, 0, 0, 0)') res='Press any button still has a fill: '+cs.backgroundColor;
     else if(cs.color!==want) res='Press any button is '+cs.color+', not the accent '+want;
     else if(getComputedStyle(ap,'::before').content!=='""') res='Press any button has no button glyph';
     else if(Math.abs(parseFloat(getComputedStyle(nm).fontSize)-32*z)>0.5) res='the wordmark is '+getComputedStyle(nm).fontSize+', not the 32px title size x '+z;
     else if(Math.abs(nm.getBoundingClientRect().left-wd*0.05)>3) res='the wordmark starts at '+Math.round(nm.getBoundingClientRect().left)+', not the 5 percent margin '+Math.round(wd*0.05);
     else if(!pg.querySelector('.aprt')||!/in the ring/i.test(pg.textContent)) res='the ring has no words';
     if(res) return res;
     oldT=window.arcadeBoardTonight; window.arcadeBoardTonight=function(){ return []; };
     pg.textContent=''; arcadeAttBoard(pg); ln=pg.querySelector('.apn');
     if(!ln) return 'the empty line left the board';
     probe=document.createElement('i'); probe.style.color='var(--tx-1)'; document.body.appendChild(probe); want=getComputedStyle(probe).color; probe.remove();
     if(getComputedStyle(ln).color!==want) res='the empty line is '+getComputedStyle(ln).color+', not the light text '+want;
     return res;
   } finally {
     try{ if(oldT) window.arcadeBoardTonight=oldT; }catch(_o){}
     try{ pg.textContent=''; pg.style.display='none'; d.style.display=wasDisp; }catch(_f){}
   }
 }},
